<div class="transform-output-wrap"><table class="enterprise-table transform-output-table" data-datatable="false" aria-label="Produits obtenus"><thead><tr><th scope="col">Produit obtenu *</th><th scope="col">Quantité (kg) *</th><th scope="col">DLC du produit *</th><th scope="col"><span class="sr-only">Retirer</span></th></tr></thead><tbody data-flow-outputs><?php $outputIndex=0;require __DIR__.'/output_row.php';?></tbody></table></div><template data-flow-output-template><?php $outputIndex='__INDEX__';require __DIR__.'/output_row.php';?></template><button type="button" class="btn-secondary" data-flow-add-output><i class="bi bi-plus-circle" aria-hidden="true"></i> Ajouter un produit</button></fieldset>
